        /// <summary>
        /// This function is used return select query sting to get the information of student.
        /// </summary>
        /// <param name="aiYearwiseStudentId"></param>
        /// <param name="aiSchoolId"></param>
        /// <param name="aiAcademicYearId"></param>
        /// <returns></returns>
        private String GetStudentDetailsSQLStatement(int aiYearwiseStudentId, int aiSchoolId, int aiAcademicYearId)
        {
            string sSelectStatement = " SELECT " +
                                            " YearWise_Student_Details.YearWise_Student_Id" +
                                            ",SchoolWise_Student_Master.Enrolment_Number" +
                                            ",Salutation_Master.Salutation_Name+' '+SchoolWise_Student_Master.First_Name +' '+ SchoolWise_Student_Master.Middle_Name+' '+SchoolWise_Student_Master.Last_Name AS StudentFullName" +
                                            ",YearWise_Student_Details.Student_Id" +
                                            " ,Standard_Master.Standard_Name+' - '+Division_Master.Division_Name AS Standard_Name " +
                                    " FROM YearWise_Student_Details INNER JOIN SchoolWise_Student_Master INNER JOIN Salutation_Master ON" +
                                            " Salutation_Master.Salutation_Id=SchoolWise_Student_Master.Salutation_Id ON " +
                                            "YearWise_Student_Details.Student_Id=SchoolWise_Student_Master.SchoolWise_Student_Id " +
                                            " INNER JOIN Standard_Master " +
                                            " ON Standard_Master.Standard_Id=YearWise_Student_Details.Standard_Id " +
                                            " INNER JOIN Division_Master " +
                                            " ON Division_Master.Division_Id=YearWise_Student_Details.Division_id " +
                                    " WHERE YearWise_Student_Details.School_Id=" + aiSchoolId +
                                           //" AND YearWise_Student_Details.Academic_Year_ID=" + aiAcademicYearId +
                                            " AND Salutation_Master.Is_Deleted=N'" + Constants.C_NO + "' " +
                                            " AND YearWise_Student_Details.Is_Deleted=N'" + Constants.C_NO + "' " +
                                            " AND SchoolWise_Student_Master.Is_Deleted=N'" + Constants.C_NO + "' " +
                                            " AND SchoolWise_Student_Master.School_Id=" + aiSchoolId +
                                            " AND SchoolWise_Student_Master.SchoolLeft_Date IS NULL" +
                                            " AND YearWise_Student_Details.YearWise_Student_Id = " + aiYearwiseStudentId;
            return sSelectStatement;
        }

